(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.02+t*0.3)*18 + Math.cos(y*0.015-t*0.2)*12 + Math.sin((x+y)*0.01+t*0.15)*8;
  const wy = Math.cos(y*0.02-t*0.25)*18 + Math.sin(x*0.018+t*0.35)*12 + Math.cos((x-y)*0.012-t*0.18)*8;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [60+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.05, 2.8],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75)*40, 0.11, 1.4]
  ];
  let aS=0, iS=0, harm=0;
  for (const [sX,sY,f,sp] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp);
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5);
    harm += Math.sin(d*f*1.3-t*sp*0.8+2.1)*0.6;
  }
  const act=aS/8, inh=iS/8, hrm=harm/8;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.08+t*0.6)*Math.sin(sy*0.06-t*0.4)*0.3;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    + Math.sin(dist*0.07+ang*2-t*0.8)*0.2;
  const ripple = Math.sin(dist*0.09-t*3)*Math.exp(-dist*0.005)*0.4;
  const noise = (Math.sin(sx*0.31+sy*0.17+t*0.7)*Math.sin(sx*0.23-sy*0.29-t*0.5)
    + Math.sin(sx*0.13+sy*0.37+t*0.9)*Math.cos(sx*0.41-sy*0.11-t*0.3))*0.25;
  const reaction = Math.tanh((act-inh*0.7+bg*0.3+spiral+ripple+hrm*0.5+noise)*2.2);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5
    +Math.sin(sx*0.22-sy*0.18+t*0.4)*0.3)*1.5)*0.3;
  const micro = Math.sin(sx*0.4+t*1.5)*Math.sin(sy*0.35-t*1.2)*0.08;
  const blend = reaction*0.6+cell*0.25+micro;
  const v = blend*0.5+0.5;
  const tShift = Math.sin(t*0.15)*0.08;
  const pal = [[6,12,52],[12,42,88],[18,88,115],[28,138,128],[55,175,135],[145,195,95],[215,185,65],[225,145,72],[195,95,75],[145,55,72],[88,28,62],[42,18,52],[6,12,52]];
  let idx = (v+tShift)*(pal.length-1);
  idx = idx<0?0:idx>pal.length-1?pal.length-1:idx;
  const i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge = Math.abs(reaction)>0.75?1.18:Math.abs(reaction)>0.5?1.06:1.0;
  const glow = Math.max(0, reaction)*0.15;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*60)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*40)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*80)|0
  ];
}
